shouldDeferPlannedSourceContainer.source:
var shouldDeferPlannedSourceContainer = function(room, plannedEntry, structureCounts, siteCounts) {
    if(!room || !plannedEntry || plannedEntry.structureType != STRUCTURE_CONTAINER) return false;

    let entry = plannedEntry.entry;
    if(!entry || entry.tag != 'source') return false;

    let requiredExtensions = CONTROLLER_STRUCTURES[STRUCTURE_EXTENSION][3] || 10;
    let currentExtensions = (structureCounts[STRUCTURE_EXTENSION] || 0) + (siteCounts[STRUCTURE_EXTENSION] || 0);
    return currentExtensions < requiredExtensions;
};

checkPlannedConstructions.source:
var checkPlannedConstructions = function() {
    if(!Memory.build) return;
    console.log('Checking planned construction sites.');
    let planned = Memory.build;
    for(let roomName in planned) {

        let room = Game.rooms[roomName];
        if(room == undefined) continue;

        let roomPlan = planned[roomName];

        let plannedEntries = [];
        let leftoversByType = {};
        let structureCounts = {};
        let siteCounts = {};

        for(let structureType in roomPlan) {
            let structuresPlanned = roomLayout.sortEntries(roomPlan[structureType] || []);
            leftoversByType[structureType] = [];
            structureCounts[structureType] = room.find(FIND_MY_STRUCTURES, {filter: {structureType: structureType}}).length;
            siteCounts[structureType] = room.find(FIND_MY_CONSTRUCTION_SITES, {filter: {structureType: structureType}}).length;

            for(let s of structuresPlanned) {
                plannedEntries.push({
                    structureType: structureType,
                    entry: s
                });
            }
        }

        plannedEntries.sort((a, b) => {
            let aEntry = a.entry;
            let bEntry = b.entry;
            if(aEntry.level != bEntry.level) return aEntry.level - bEntry.level;
            if((aEntry.distance || 0) != (bEntry.distance || 0)) return (aEntry.distance || 0) - (bEntry.distance || 0);
            if((aEntry.priority || 0) != (bEntry.priority || 0)) return (aEntry.priority || 0) - (bEntry.priority || 0);
            if(a.structureType == STRUCTURE_ROAD && b.structureType != STRUCTURE_ROAD) return 1;
            if(a.structureType != STRUCTURE_ROAD && b.structureType == STRUCTURE_ROAD) return -1;
            if(a.structureType != b.structureType) return a.structureType.localeCompare(b.structureType);
            return (aEntry.key || '').localeCompare(bEntry.key || '');
        });

        let doneStructure = false;
        for(let plannedEntry of plannedEntries) {
            let structureType = plannedEntry.structureType;
            let s = plannedEntry.entry;

            if(doneStructure) {
                leftoversByType[structureType].push(s);
                continue;
            }

            let p = new RoomPosition(s.pos.x, s.pos.y, roomName);
            if(p.lookFor(LOOK_STRUCTURES).filter((structure)=>structure.structureType == structureType).length > 0) {
                continue;
            }
            if(p.lookFor(LOOK_CONSTRUCTION_SITES).filter((site)=>site.structureType == structureType).length > 0) {
                siteCounts[structureType]++;
                continue;
            }

            if(s.level > room.controller.level) {
                leftoversByType[structureType].push(s);
                continue;
            }

            if(shouldDeferPlannedSourceContainer(room, plannedEntry, structureCounts, siteCounts)) {
                leftoversByType[structureType].push(s);
                continue;
            }

            let maxStructures = CONTROLLER_STRUCTURES[structureType][room.controller.level];
            let currentStructures = structureCounts[structureType];
            let currentSites = siteCounts[structureType];
            if(structureType == STRUCTURE_SPAWN) console.log('current/max spawns in '+roomName+": "+currentStructures+'/'+maxStructures);

            if(currentStructures + currentSites < maxStructures) {
                let result = room.createConstructionSite(s.pos.x, s.pos.y, structureType);
                if(result == OK) {
                    doneStructure = true;
                    siteCounts[structureType]++;
                    continue;
                }
                if(result == ERR_FULL) {
                    leftoversByType[structureType].push(s);
                    doneStructure = true;
                    continue;
                }
            }

            leftoversByType[structureType].push(s);
        }

        for(let structureType in roomPlan) {
            Memory.build[roomName][structureType] = leftoversByType[structureType] || [];
        }
    }
};

selectRoomLayoutStrategy.source:
var selectRoomLayoutStrategy = function(room) {
    let preferredStrategy = ROOM_LAYOUT_STRATEGIES[0];
    if(preferredStrategy.canFitRoom(room)) return preferredStrategy;

    let viableStrategies = ROOM_LAYOUT_STRATEGIES.filter((strategy) => strategy.canFitRoom(room));
    viableStrategies.sort((a, b) => {
        let scoreDifference = b.getSuitabilityScore(room) - a.getSuitabilityScore(room);
        if(scoreDifference != 0) return scoreDifference;
        return ROOM_LAYOUT_STRATEGIES.indexOf(a) - ROOM_LAYOUT_STRATEGIES.indexOf(b);
    });

    return viableStrategies[0] || preferredStrategy;
};

buildRoadPath.source:
var buildRoadPath = function(room, startPos, goalPos, reserved, preferredRoadKeys) {
    if(!startPos || !goalPos) return [];
    let analysis = getRoomAnalysis(room);

    let result = PathFinder.search(startPos, { pos: goalPos, range: 1 }, {
        maxRooms: 1,
        plainCost: 2,
        swampCost: 2,
        roomCallback(roomName) {
            if(roomName != room.name) return false;
            let matrix = analysis.baseRoadMatrix.clone();

            for(let key of reserved) {
                let parts = key.split(':');
                matrix.set(Number(parts[0]), Number(parts[1]), 255);
            }

            for(let key of preferredRoadKeys || []) {
                let parts = key.split(':');
                matrix.set(Number(parts[0]), Number(parts[1]), 1);
            }

            return matrix;
        }
    });

    return result.path || [];
};

