anchorFromWorld.source:
var anchorFromWorld = function(pos, relative) {
    return {
        x: pos.x - relative.x,
        y: pos.y - relative.y
    };
};

sortEntries.source:
var sortEntries = function(entries) {
    entries.sort((a, b) => {
        if(a.level != b.level) return a.level - b.level;
        if((a.distance || 0) != (b.distance || 0)) return (a.distance || 0) - (b.distance || 0);
        if((a.priority || 0) != (b.priority || 0)) return (a.priority || 0) - (b.priority || 0);
        return buildKey(a.t, a.pos).localeCompare(buildKey(b.t, b.pos));
    });
    return entries;
};

buildKey.source:
var buildKey = function(type, pos) {
    return type + ':' + pos.x + ':' + pos.y;
};

buildRoadScavengerBody.source:
var buildRoadScavengerBody = function(budget) {
    let body = [];
    let cappedBudget = budget;
    if(cappedBudget > 1600) cappedBudget = 1600;

    let triads = Math.min(Math.floor(cappedBudget / 150), 16);
    for(let i = 0; i < triads; i++) {
        body.push(CARRY, CARRY, MOVE);
    }

    let remainder = cappedBudget - triads * 150;
    if(body.length == 0 && cappedBudget >= 100) {
        body.push(CARRY, MOVE);
    } else if(remainder >= 100 && body.length <= 48) {
        body.push(CARRY, MOVE);
    }

    return body;
};

getCarryCapacityForBody.source:
var getCarryCapacityForBody = function(body) {
    let carryParts = 0;
    for(let part of body || []) {
        if(part == CARRY) carryParts++;
    }
    return carryParts * CARRY_CAPACITY;
};

ensureRecoveryMemory.source:
var ensureRecoveryMemory = function() {
    if(!Memory.manager) Memory.manager = {};
    if(!Memory.manager.energyRecovery) Memory.manager.energyRecovery = {};
    if(!Memory.manager.energyRecovery.rooms) Memory.manager.energyRecovery.rooms = {};
    return Memory.manager.energyRecovery;
};

getStoredEnergy.source:
var getStoredEnergy = function(room) {
    if(!room) return 0;

    let total = 0;
    if(room.storage && room.storage.store) total += room.storage.store[RESOURCE_ENERGY] || 0;
    if(room.terminal && room.terminal.store) total += room.terminal.store[RESOURCE_ENERGY] || 0;
    return total;
};

isEligibleRecoveryRoom.source:
var isEligibleRecoveryRoom = function(room) {
    return !!(room && room.controller && room.controller.my && room.controller.level >= 5);
};

getDonorRooms.source:
var getDonorRooms = function(targetRoom, ownedRooms) {
    return ownedRooms
        .filter((room) => room.name != targetRoom.name)
        .filter((room) => Game.map.getRoomLinearDistance(room.name, targetRoom.name) <= RECOVERY_DONOR_MAX_DISTANCE)
        .filter((room) => getStoredEnergy(room) > RECOVERY_DONOR_MIN_ENERGY)
        .sort((a, b) => {
            let distanceDifference = Game.map.getRoomLinearDistance(a.name, targetRoom.name)
                - Game.map.getRoomLinearDistance(b.name, targetRoom.name);
            if(distanceDifference != 0) return distanceDifference;
            return getStoredEnergy(b) - getStoredEnergy(a);
        });
};

refreshRecoveryStates.source:
var refreshRecoveryStates = function(ownedRooms) {
    let recoveryMemory = ensureRecoveryMemory();
    let activeTargets = new Set();

    for(let room of ownedRooms) {
        if(!isEligibleRecoveryRoom(room)) {
            delete recoveryMemory.rooms[room.name];
            continue;
        }

        let storedEnergy = getStoredEnergy(room);
        let currentState = recoveryMemory.rooms[room.name] || {};
        let isActive = currentState.active
            ? storedEnergy < RECOVERY_EXIT_ENERGY
            : storedEnergy < RECOVERY_TRIGGER_ENERGY;

        recoveryMemory.rooms[room.name] = {
            roomName: room.name,
            active: isActive,
            checkedAt: Game.time,
            storedEnergy: storedEnergy,
            donorRequests: isActive
                ? getDonorRooms(room, ownedRooms).map((donorRoom) => ({
                    donorRoom: donorRoom.name,
                    targetRoom: room.name,
                    requestedEnergy: RECOVERY_SUPPORT_BATCH
                }))
                : []
        };

        if(isActive) activeTargets.add(room.name);
    }

    for(let roomName in recoveryMemory.rooms) {
        if(!activeTargets.has(roomName) && recoveryMemory.rooms[roomName]) {
            recoveryMemory.rooms[roomName].donorRequests = [];
        }
    }
};

processClaimFlags.source:
var processClaimFlags = function() {
    let claimFlags = _.filter(Game.flags, (flag) => flag.name.indexOf('CreateRoom') > -1);
    for(let flag of claimFlags) {
        let parts = flag.name.split(':');
        if(parts.length < 2 || parts[0] != 'CreateRoom') continue;

        let homeRoomName = parts[1];
        if(!homeRoomName) continue;

        let override = flag.name.indexOf('Override') > -1;
        let queueResult = queueClaimIntent(homeRoomName, flag.pos, {
            override: override,
            auto: flag.name.indexOf('AutoExpand') > -1,
            source: 'flag',
            targetRoomName: flag.pos.roomName
        });

        if(queueResult == OK) {
            console.log('CLAIM - Parsed ' + flag.name + ' into Memory.manager.claims for ' + homeRoomName + ' -> ' + flag.pos.roomName + '.');
            flag.remove();
        }
    }
};

processMiningFlags.source:
var processMiningFlags = function() {
    let miningFlags = _.filter(Game.flags, (f)=>f.name.indexOf('Mine') > -1);
    for(let m in miningFlags) {
        let miningFlag = miningFlags[m];
        let owner = miningFlag.name.split(':')[1];
        let result = addSource(miningFlag.pos, owner);
        if(result == OK) {
            console.log('PROCESS MINING FLAGS - Processed '+miningFlag.name);
            miningFlag.remove();
            if(Memory.paths[miningFlag.name]) Memory.paths[miningFlag.name] = undefined;
        } else if (result == -1) {
            let targetRoom = miningFlag.pos.roomName;
            console.log('PROCESS MINING FLAGS - Cannot process '+miningFlag.name+' because there is no visibility in '+targetRoom+'.');

            if(queueVisibilityScout(owner, targetRoom)) {
                console.log('PROCESS MINING FLAGS - Queued scout from '+owner+' to scout '+targetRoom+'.');
            }
        } else {
            console.log('PROCESS MINING FLAGS - ERROR!!! Could not process '+miningFlag.name+' Returned error: '+result);
        }
    }
};

isTrackedRemoteMiner.source:
var isTrackedRemoteMiner = function(creep) {
    return !!(creep
        && creep.memory
        && creep.memory.role == 'miner'
        && creep.memory.homeRoom
        && creep.memory.assignedNode
        && creep.memory.assignedNode.roomName
        && creep.memory.assignedNode.roomName != creep.memory.homeRoom
        && creep.memory.sourceId);
};

updateRemoteReachability.source:
var updateRemoteReachability = function(creep, reachedSource) {
    if(!isTrackedRemoteMiner(creep)) return;

    if(reachedSource) {
        if(creep.memory.remoteSourceReached) return;
        creep.memory.remoteSourceReached = true;
        creep.memory.remoteReachabilityReported = 'success';
        remoteManager.recordRemoteMinerReachability(
            creep.memory.homeRoom,
            creep.memory.sourceId,
            creep.memory.assignedNode.roomName,
            true
        );
        return;
    }

    if(creep.memory.remoteSourceReached) return;
    if(creep.memory.remoteReachabilityReported == 'failure') return;
    if(creep.spawning || creep.ticksToLive === undefined || creep.ticksToLive > 1) return;

    creep.memory.remoteReachabilityReported = 'failure';
    remoteManager.recordRemoteMinerReachability(
        creep.memory.homeRoom,
        creep.memory.sourceId,
        creep.memory.assignedNode.roomName,
        false
    );
};

clearRecoverySupportMemory.source:
var clearRecoverySupportMemory = function(creep) {
    creep.memory.energyRecoverySupport = undefined;
    creep.memory.jobs = undefined;
    creep.memory.status = STATUS_IDLE;
    creep.memory.assignedNode = undefined;
    creep.memory.currentRoom = undefined;
    creep.memory.currentPath = undefined;
    creep.memory.pathIndex = undefined;
};

getRecoveryEnergySource.source:
var getRecoveryEnergySource = function(homeRoom) {
    if(homeRoom && homeRoom.storage && homeRoom.storage.store[RESOURCE_ENERGY] > 0) return homeRoom.storage;
    if(homeRoom && homeRoom.terminal && homeRoom.terminal.store[RESOURCE_ENERGY] > 0) return homeRoom.terminal;
};

getRecoveryEnergyDropoff.source:
var getRecoveryEnergyDropoff = function(targetRoom) {
    if(!targetRoom) return;
    if(targetRoom.storage) return targetRoom.storage;
    if(targetRoom.terminal) return targetRoom.terminal;

    let spawns = targetRoom.find(FIND_MY_SPAWNS, {
        filter: (spawn) => spawn.energy < spawn.energyCapacity
    });
    if(spawns.length > 0) return spawns[0];

    let extensions = targetRoom.find(FIND_MY_STRUCTURES, {
        filter: (structure) => structure.structureType == STRUCTURE_EXTENSION && structure.energy < structure.energyCapacity
    });
    if(extensions.length > 0) return extensions[0];
};

runRecoverySupportCourier.source:
var runRecoverySupportCourier = function(creep) {
    let support = creep.memory.energyRecoverySupport;
    if(!support) return false;

    let homeRoom = Game.rooms[creep.memory.homeRoom];
    let targetRoom = Game.rooms[support.targetRoom];
    let targetStillNeedsSupport = roomEnergyRecovery.isRecoveryActive(support.targetRoom);

    if(!targetStillNeedsSupport && _.sum(creep.carry) == 0) {
        if(creep.room.name != creep.memory.homeRoom) {
            let fallback = homeRoom && homeRoom.storage ? homeRoom.storage.pos : new RoomPosition(25, 25, creep.memory.homeRoom);
            creep.moveTo(fallback, {reusePath: 5, maxRooms: 16});
            return true;
        }

        clearRecoverySupportMemory(creep);
        return false;
    }

    if(_.sum(creep.carry) == 0) {
        let source = getRecoveryEnergySource(homeRoom);
        if(!source) return true;

        if(creep.room.name != source.pos.roomName || creep.pos.getRangeTo(source) > 1) {
            creep.moveTo(source, {reusePath: 10, maxRooms: 16});
            return true;
        }

        creep.withdraw(source, RESOURCE_ENERGY);
        return true;
    }

    let dropoff = getRecoveryEnergyDropoff(targetRoom);
    if(!dropoff) {
        creep.moveTo(new RoomPosition(25, 25, support.targetRoom), {reusePath: 10, maxRooms: 16});
        return true;
    }

    if(creep.room.name != dropoff.pos.roomName || creep.pos.getRangeTo(dropoff) > 1) {
        creep.moveTo(dropoff, {reusePath: 10, maxRooms: 16});
        return true;
    }

    let transferResult = creep.transfer(dropoff, RESOURCE_ENERGY);
    if(transferResult == ERR_FULL && targetRoom && targetRoom.storage && dropoff.id != targetRoom.storage.id) {
        creep.transfer(targetRoom.storage, RESOURCE_ENERGY);
    }

    return true;
};
